```javascript
import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color, float } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-stat-tile';
  group.position.set(0, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const timelines = [];
  const disposables = [];

  // Fallback machined surface plate while GLB loads / in case of failure
  const plateGeo = new THREE.BoxGeometry(1.4, 0.9, 0.08);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.colorNode = color(colors.surface);
  plateMat.metalnessNode = float(0.5);
  plateMat.roughnessNode = float(0.55);
  disposables.push(plateGeo, plateMat);
  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.name = 'stat-tile-plate';
  group.add(plate);

  // Rim light accent edge
  const rimGeo = new THREE.BoxGeometry(1.44, 0.02, 0.1);
  const rimMat = new MeshStandardNodeMaterial();
  rimMat.colorNode = color(colors.accent);
  rimMat.metalnessNode = float(0.2);
  rimMat.roughnessNode = float(0.4);
  disposables.push(rimGeo, rimMat);
  const rim = new THREE.Mesh(rimGeo, rimMat);
  rim.position.set(0, -0.44, 0.02);
  rim.name = 'stat-tile-rim';
  group.add(rim);

  let meshRoot = null;
  try {
    const gltf = ctx.glbLoader.load(config.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb');
    if (gltf && gltf.scene) {
      meshRoot = gltf.scene;
      meshRoot.name = 'stat-tile-gear';
      meshRoot.scale.set(0.4, 0.4, 0.4);
      meshRoot.position.set(0, 0, 0.1);
      group.add(meshRoot);
    }
  } catch (e) {
    // fallback silently, plate remains visible
  }

  // Value + label text via MSDF atlas (no numeric content specified — render placeholder metric)
  let textMeshes = [];
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    const valueText = ctx.fontAtlas.createText({
      text: '—',
      font: 'display',
      weight: 600,
      size: 0.34,
      color: colors.paper,
      atlasIndex: 0,
      atlasRect: [0, 0, 512, 320],
    });
    if (valueText) {
      valueText.position.set(0, 0.12, 0.06);
      valueText.name = 'stat-tile-value';
      group.add(valueText);
      textMeshes.push(valueText);
    }

    const labelText = ctx.fontAtlas.createText({
      text: 'METRIC',
      font: 'text',
      weight: 700,
      size: 0.09,
      color: colors.ink,
      atlasIndex: 0,
      atlasRect: [0, 0, 512, 320],
    });
    if (labelText) {
      labelText.position.set(0, -0.24, 0.06);
      labelText.name = 'stat-tile-label';
      group.add(labelText);
      textMeshes.push(labelText);
    }
  }

  // Cinematic primitives
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  }
  if (ctx.primitives && ctx.primitives['magnetic-cursor']) {
    ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35 });
  }

  const baseY = group.position.y;
  const baseScale = { x: group.scale.x, y: group.scale.y, z: group.scale.z };

  function onHoverIn() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.35, ease: 'power3.out' });
    timelines.push(tl);
  }

  function onHoverOut() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.35, ease: 'power3.out' });
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: baseScale.x * 0.97, y: baseScale.y * 0.97, z: baseScale.z * 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: baseScale.x, y: baseScale.y, z: baseScale.z, duration: 0.12, ease: 'back.out' });
    timelines.push(tl);
    if (group.userData.emit) {
      group.userData.emit('hub-collection.select');
    }
  }

  // Entrance: weighted-settle
  const entranceTl = gsap.timeline();
  group.scale.set(baseScale.x * 1.04, baseScale.y * 1.04, baseScale.z * 1.04);
  entranceTl.to(group.scale, {
    x: baseScale.x,
    y: baseScale.y,
    z: baseScale.z,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  group.userData.handlers = {
    hover: onHoverIn,
    hoverEnd: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    textMeshes.forEach((t) => {
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
    if (meshRoot) {
      meshRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
